"""The README's table of supported models, generated by scripts/gen_supported_models.py.

Against the manifest's floor library, the version every user is guaranteed to have, the README
must match what the generator writes. Against a newer library (CI's ``newest`` job), every model
it lists must still be supported: a newer library may add models, never drop them.
"""

from __future__ import annotations

from importlib.metadata import version
import importlib.util
import json
from pathlib import Path
import re
from types import ModuleType

from govee_ble_local import supported_skus
from packaging.requirements import Requirement
from packaging.version import Version

ROOT = Path(__file__).resolve().parent.parent


def _generator() -> ModuleType:
    """Load scripts/gen_supported_models.py (a script, not a package module)."""
    spec = importlib.util.spec_from_file_location(
        "gen_supported_models", ROOT / "scripts" / "gen_supported_models.py"
    )
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _floor() -> Version:
    """The library version the manifest's range starts at."""
    manifest = json.loads(
        (ROOT / "custom_components" / "govee_ble_local" / "manifest.json").read_text(
            encoding="utf-8"
        )
    )
    (lower,) = [s for s in Requirement(manifest["requirements"][0]).specifier if s.operator == ">="]
    return Version(lower.version)


def test_the_readme_lists_the_supported_models() -> None:
    """Up to date at the floor library; a newer library still supports every listed model."""
    generator = _generator()
    block = generator.block_in(generator.README.read_text(encoding="utf-8"))
    if Version(version("govee-ble-local")) == _floor():
        assert block == generator.render(), (
            "README.md's model table is out of date: run scripts/gen_supported_models.py"
        )
        return
    listed = set(re.findall(r"^\| ([A-Z][A-Z0-9]+) \|", block, re.MULTILINE))
    assert listed
    assert listed <= set(supported_skus(allow_modelled=True))
